    """
    Calculates P = y^x * z^y * x^z.
    Returns P if P is a positive integer, otherwise returns None.
    Handles integer exponentiation, specifically issues with negative bases 
    and integer exponents.
    """

    def safe_power(base, exp):
        if exp == 0:
            return 1
        if base == 0:
            return 0 if exp > 0 else None # 0^0=1 handled above, 0^k=0 for k>0, 0^k=undef for k<0

        if exp < 0:
            # If the result must be an integer, the base must be 1 or -1 for negative exponents
            if abs(base) != 1:
                return None # Result is fractional

            # If base is 1 or -1, the result is an integer (1 or -1)
            if base == 1:
                return 1
            if base == -1:
                return (-1)**exp # Integer result

        # Standard integer exponentiation
        try:
            return base**exp
        except OverflowError:
            return None


    term1 = safe_power(y, x)
    term2 = safe_power(z, y)
    term3 = safe_power(x, z)

    if term1 is None or term2 is None or term3 is None:
        return None

    P = term1 * term2 * term3

    # Final check: must be a positive integer prime
    return P if isinstance(P, int) and P > 0 else None


def find_good_triples(S_limit=100):
    good_triples = []

    # Search bounds: |x|, |y|, |z| <= 10 since 11^2 = 121 > 100
    search_range = range(-10, 11)

    for x in search_range:
        for y in search_range:
            for z in search_range:
                S = x**2 + y**2 + z**2
                if S > S_limit:
                    continue

                P = calculate_P(x, y, z)

                if P is not None and is_prime(P):
                    good_triples.append(((x, y, z), S))

    # Sort by S, then by lexicographical order (as required by enumeration rule)
    good_triples.sort(key=lambda item: (item[1], item[0]))

    return good_triples

